import numpy as np
import os

# Check Suite2p ops for baseline parameters
base = '/app/data/jm031/2023-10-18_a'
ops = np.load(os.path.join(base, 'suite2p/plane0/ops.npy'), allow_pickle=True).item()

# Print relevant keys
for k in sorted(ops.keys()):
    v = ops[k]
    if isinstance(v, (int, float, str, bool, type(None))):
        print(f"  {k}: {v}")
    elif isinstance(v, np.ndarray) and v.size < 10:
        print(f"  {k}: {v}")
    elif isinstance(v, np.ndarray):
        print(f"  {k}: ndarray shape={v.shape} dtype={v.dtype}")
    elif isinstance(v, list) and len(v) < 10:
        print(f"  {k}: {v}")
    else:
        print(f"  {k}: {type(v).__name__}")
